    // Match:  word: Type  where Type is followed by , or ) or =
    result = result.replace(/(\(\s*\w+|\,\s*\w+)\s*:\s*(?:Record<[^>]+>|Array<[^>]+>|[A-Za-z]\w*(?:\[\])?(?:\s*\|\s*[A-Za-z]\w*(?:\[\])?)*)\s*([,\)=])/g, "$1 $2");
